        {{ null_junk('"WAGE_RELATED_COSTS_FOR_PART"') }} as wage_related_costs_for_part,
        {{ null_junk('"WAGE_RELATED_COSTS_RHC_FQHC"') }} as wage_related_costs_rhc_fqhc,
        {{ null_junk('"MORTGAGE_PAYABLE"') }} as mortgage_payable,
        INGESTED_AT as _loaded_at,
        'https://opendata.utah.gov/d/qb3x-weh7' as _source_url,
    'ENT_' || LEFT(MD5('CCN' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', ''))) = 0 OR LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', ''))) > 6 OR NOT REGEXP_LIKE(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), '^[0-9]+$') OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 6, '0') = REPEAT('0', 6) OR (LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', ''))) >= 4 AND UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')) = REPEAT(LEFT(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 1), LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', ''))))) OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 6, '0') = REPEAT(LEFT(LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 6, '0'), 1), 6) OR UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')) IN ('123456789', '987654321', '1234567890', '0987654321', '12345678', '87654321', '123456', '654321') OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 6, '0') IN ('123456789', '987654321', '1234567890', '0987654321', '12345678', '87654321', '123456', '654321') THEN NULL ELSE LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("PROVIDER_CCN"), '[^0-9A-Za-z]', '')), 6, '0') END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

)

